      "content": "export function buildTimeline(input) {
  // Validate input is non-null object
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  // Validate runId: bounded string (1..128)
  const { runId, events } = input;
  if (typeof runId !== 'string' || runId.length < 1 || runId.length > 128) {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  // Validate events is array (may be empty)
  if (!Array.isArray(events)) {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  if (events.length > 200) {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  const validStatuses = new Set(['PASS', 'FAIL', 'NOT_RUN', 'ERROR', 'INCONCLUSIVE', 'CANCELLED', 'TIMED_OUT']);
  const seenIds = new Set();
  const validatedEvents = [];

  for (let i = 0; i < events.length; i++) {
    const e = events[i];
    if (e === null || typeof e !== 'object' || Array.isArray(e)) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // Exact keys
    const keys = Object.keys(e);
    if (keys.length !== 7 || !keys.includes('id') || !keys.includes('attempt') || !keys.includes('stage') ||
        !keys.includes('status') || !keys.includes('createdAt') || !keys.includes('durationMs') ||
        !keys.includes('receiptId')) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // id: bounded string, unique
    const id = e.id;
    if (typeof id !== 'string' || id.length < 1 || id.length > 128 || seenIds.has(id)) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }
    seenIds.add(id);

    // attempt: nonnegative safe integer, no -0
    const attempt = e.attempt;
    if (!Number.isInteger(attempt) || attempt < 0 || Object.is(attempt, -0)) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // stage: bounded string (1..128)
    const stage = e.stage;
    if (typeof stage !== 'string' || stage.length < 1 || stage.length > 128) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // status: exact enum
    const status = e.status;
    if (!validStatuses.has(status)) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // createdAt: nonnegative safe integer, no -0
    const createdAt = e.createdAt;
    if (!Number.isInteger(createdAt) || createdAt < 0 || Object.is(createdAt, -0)) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // durationMs: null or finite >= 0, no -0
    const durationMs = e.durationMs;
    if (durationMs !== null) {
      if (typeof durationMs !== 'number' || !Number.isFinite(durationMs) || durationMs < 0 || Object.is(durationMs, -0)) {
        return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
      }
    }

    // receiptId: null or bounded string (1..128)
    const receiptId = e.receiptId;
    if (receiptId !== null) {
      if (typeof receiptId !== 'string' || receiptId.length < 1 || receiptId.length > 128) {
        return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
      }
    }

    // Copy event fields
    validatedEvents.push({
      id,
      attempt,
      stage,
      status,
      createdAt,
      durationMs,
      receiptId,
      _originalIndex: i
    });
  }

  // Sort: attempt asc, createdAt asc, original index asc
  validatedEvents.sort((a, b) => {
    if (a.attempt !== b.attempt) return a.attempt - b.attempt;
    if (a.createdAt !== b.createdAt) return a.createdAt - b.createdAt;
    return a._originalIndex - b._originalIndex;
  });

  // Build events output (remove _originalIndex)
  const eventsOutput = validatedEvents.map(e => ({
    id: e.id,
    attempt: e.attempt,
    stage: e.stage,
    status: e.status,
    createdAt: e.createdAt,
    durationMs: e.durationMs,
    receiptId: e.receiptId
  }));

  // Build attempts: group by attempt, count unknown durations
  const attemptsMap = new Map();
  for (const e of validatedEvents) {
    const key = e.attempt;
    if (!attemptsMap.has(key)) {
      attemptsMap.set(key, { eventIds: [], unknownDurations: 0 });
    }
    const group = attemptsMap.get(key);
    group.eventIds.push(e.id);
    if (e.durationMs === null) group.unknownDurations++;
  }

  const attemptsOutput = [];
  for (const [attempt] of attemptsMap) {
    attemptsOutput.push({
      attempt,
      eventIds: attemptsMap.get(attempt).eventIds,
      unknownDurations: attemptsMap.get(attempt).unknownDurations
    });
  }

  // Sort attempts ascending by attempt
  attemptsOutput.sort((a, b) => a.attempt - b.attempt);

  return {
    schemaVersion: 1,
    status: 'READY',
    runId,
    events: eventsOutput,
    attempts: attemptsOutput,
    authorizing: false
  };
